def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    value = v1 - v2

    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "operation": "difference",
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": "monetary"
            }
        }
    }
